def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); best=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
                        seen.add((x,y)); stack.append((x,y))
            r0=min(a for a,b in cells); r1=max(a for a,b in cells)
            c0=min(b for a,b in cells); c1=max(b for a,b in cells)
            n=sum(grid[a][b]==0 for a in range(r0,r1+1) for b in range(c0,c1+1))
            best=max(best,n)
    return [[0]*best]

